const ScorecardImport=(function(){function _nums(line){const out=[];const re=/-?\d+/g;let m;while((m=re.exec(line))!==null)out.push(parseInt(m[0],10));return out}function _label(line){return String(line||"").toLowerCase()}function _stripSubtotals(vals,holeCount){if(vals.length===holeCount)return vals;const half=Math.floor(holeCount/2);if(holeCount===18&&vals.length===21){return vals.slice(0,9).concat(vals.slice(10,19))}if(holeCount===18&&vals.length===20){return vals.slice(0,9).concat(vals.slice(10,19))}if(vals.length===holeCount+1)return vals.slice(0,holeCount);if(vals.length===half+1&&holeCount===9)return vals.slice(0,holeCount);return vals}const _isPar=vals=>vals.every(v=>v>=3&&v<=6);const _isYards=vals=>vals.every(v=>v>=60&&v<=800)&&vals.some(v=>v>=100);const _isIndex=(vals,n)=>{if(!vals.every(v=>v>=1&&v<=n))return false;return new Set(vals).size===vals.length};function parseScorecard(text,holeCount){const n=holeCount===9?9:18;const half=Math.floor(n/2);const raw=String(text||"");const lines=raw.split(/[\r\n]+/).map(l=>l.trim()).filter(Boolean);const result={par:null,yds:null,hdcp:null,notes:[]};const labelled={par:/\bpar\b/,yds:/\b(yard|yds|yd|length|dist)/,hdcp:/\b(hcp|hdcp|handicap|index|s\.?i\.?|stroke)/};const unlabelled=[];for(const line of lines){const label=_label(line);const vals=_stripSubtotals(_nums(line),n);if(vals.length<2)continue;let claimed=null;for(const key of["par","yds","hdcp"]){if(labelled[key].test(label)){claimed=key;break}}if(claimed&&!result[claimed]&&vals.length===n){result[claimed]=vals;continue}if(claimed&&!result[claimed]&&vals.length===half){unlabelled.push({vals,claimed});continue}unlabelled.push({vals,claimed:null})}const stitched=[];for(let i=0;i<unlabelled.length;i++){const a=unlabelled[i];const b=unlabelled[i+1];if(n===18&&a.vals.length===9&&b&&b.vals.length===9&&(a.claimed===b.claimed||!a.claimed||!b.claimed)){stitched.push({vals:a.vals.concat(b.vals),claimed:a.claimed||b.claimed});i++}else{stitched.push(a)}}if(!stitched.some(x=>x.vals.length===n)){const flat=_nums(raw);for(const size of[n*3,n*2,n]){if(flat.length===size){for(let k=0;k<size/n;k++)stitched.push({vals:flat.slice(k*n,(k+1)*n),claimed:null});break}}}for(const row of stitched){if(row.vals.length!==n)continue;const key=row.claimed||(_isPar(row.vals)?"par":_isIndex(row.vals,n)?"hdcp":_isYards(row.vals)?"yds":null);if(key&&!result[key])result[key]=row.vals}if(result.par&&!result.hdcp&&_isIndex(result.par,n)&&!_isPar(result.par)){result.hdcp=result.par;result.par=null}if(!result.par)result.notes.push("No par row found — enter par below.");if(!result.hdcp)result.notes.push("No stroke-index row found — enter it below (it drives every handicap stroke).");if(!result.yds)result.notes.push("No yardages found — they are optional.");return result}function validate(parsed,holeCount){const n=holeCount===9?9:18;const problems=[];if(parsed.par){if(parsed.par.length!==n)problems.push(`Par row has ${parsed.par.length} holes, expected ${n}.`);const total=parsed.par.reduce((a,b)=>a+b,0);const lo=n===9?31:62,hi=n===9?40:80;if(total<lo||total>hi)problems.push(`Total par of ${total} looks wrong for ${n} holes.`)}if(parsed.hdcp){const sorted=parsed.hdcp.slice().sort((a,b)=>a-b);const expected=Array.from({length:n},(_,i)=>i+1);if(sorted.join(",")!==expected.join(",")){problems.push(`Stroke indexes must be 1–${n} with no repeats.`)}}return problems}return{parseScorecard,validate}})();if(typeof window!=="undefined"){Object.assign(window,{ScorecardImport})}
